-- ============================================================================
-- Historical import: custom wallpaper production rows from the vendor spreadsheets
-- (~/Downloads/indura updates.xlsx, sheets "Indura" and "Life n Color").
--
-- Run AFTER docs/coe_dashboard.sql. Safe to re-run: ON CONFLICT DO NOTHING against the
-- (pi, md_id) unique index, so a second run inserts nothing and changes nothing.
--
-- WHAT THIS DOES AND DOESN'T CARRY OVER
--   * The sheet records only WHETHER each step happened (Yes / blank / "Changes Suggested" /
--     "No Reply" / "PO cancelled"), never WHEN. Every completed step is therefore stamped with
--     the order-placed date and the row is flagged imported=true. `mdWpDurations` skips
--     imported rows entirely, so these can't pollute the step-timing medians, and the SLA
--     badge shows "N days since the order was placed" instead of a breach verdict.
--     The funnels — which step each order reached — are fully valid, and that is the question
--     the historical ticks can actually answer.
--   * The sheet has no customer name, phone or BM. Those are filled in HERE, at import time,
--     by matching the enquiry ID against install_orders and then audit_orders — so imported
--     rows are still callable. Where neither table has the enquiry, they stay blank.
--   * Where the same (ENQ, MD ID) appears as several daily snapshots, the LATEST snapshot's
--     ticks win (a later row can legitimately regress — one PO was un-dispatched because it
--     got cancelled) and the notes from every snapshot are merged.
--
-- Source rows read: 94   Skipped (unusable ENQ/MD ID): 0   Skipped (no date): 0
-- Duplicate snapshots merged: 4   Rows inserted: 90   Of those, cancelled: 7
-- ============================================================================

ALTER TABLE wp_production ADD COLUMN IF NOT EXISTS imported boolean DEFAULT false;

INSERT INTO wp_production
  (pi, md_id, vendor, order_placed_at, stages, rounds, state, notes, log,
   customer_name, phone, bm, bm_email, city, install_order_id, audit_order_id, imported)
