  v.pi, v.md_id, v.vendor, v.order_placed_at, v.stages, v.rounds, v.state, v.notes, v.log,
  COALESCE(io.customer_name, ao.customer_name),
  COALESCE(io.phone,         ao.phone),
  COALESCE(io.bm,            ao.bm),
  ao.bm_email,
  COALESCE(io.city,          ao.city),
  io.id, ao.id,
  true
