) AS v(pi, md_id, vendor, order_placed_at, stages, rounds, state, notes, log)
LEFT JOIN LATERAL (
  SELECT i.id, i.customer_name, i.phone, i.bm, i.city
  FROM install_orders i
  WHERE i.pi = v.pi AND i.status <> 'deleted'
  ORDER BY i.created_at LIMIT 1
) io ON true
LEFT JOIN LATERAL (
  SELECT a.id, a.customer_name, a.phone, a.bm, a.bm_email, a.city
  FROM audit_orders a
  WHERE a.pi = v.pi AND a.status <> 'deleted'
  ORDER BY a.created_at LIMIT 1
) ao ON true
ON CONFLICT (pi, md_id) DO NOTHING;

-- How many landed, and how many got matched to a real customer:
SELECT count(*) FILTER (WHERE imported)                        AS imported_rows,
       count(*) FILTER (WHERE imported AND phone IS NOT NULL)  AS matched_to_a_customer,
       count(*) FILTER (WHERE imported AND state = 'cancelled') AS cancelled
FROM wp_production;
